window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a19913e1c85e687e"]={"versions": [{"id": "FIG-a19913e1c85e687e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Komponentendiagramm / VFB-Architekturübersicht (Virtual Function Bus) auf Ebene der AUTOSAR-Applikationsschicht (<code>Application Layer</code>).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der domänenübergreifenden Schnittstellenbeziehungen (<em>Inter Domain Dependencies</em>) zwischen den Software-Komponenten (<code>ApplicationSwComponentType</code>) der Fahrwerk-Domäne (<em>Chassis Domain</em>) und externen Fahrzeugdomänen (<em>Powertrain</em>, <em>Body</em>, <em>HMI</em>, <em>P&amp;P Safety</em>).\n</li><li><strong>Funktionale Einordnung:</strong> Dient als Allokations- und Integrationsreferenz zur Entkopplung logischer Steuerungsfunktionen (Längs-, Quer- und Vertikaldynamik) von der physischen Steuergeräte-Topologie (z. B. Bremsen-, Lenkungs- oder Dämpfer-ECUs).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Chassis Domain Software-Komponenten (<code>SW-C</code>)</h5>\n<ul class=\"fig-list\"><li><strong>Längsdynamik &amp; Verzögerung:</strong>\n<ul class=\"fig-list\"><li><code>CrsCtrlAndAcc</code>: Cruise Control &amp; Adaptive Cruise Control (Geschwindigkeits- und Abstandsregelung).\n</li><li><code>Vlc</code>: Vehicle Longitudinal Control (Längsdynamikkoordinator / Traktions- und Bremsarbitrierung).\n</li><li><code>Ssm</code>: Secondary Slip Management / Safe State Management (Sollwertvorgabe und Sicherheitsüberwachung).\n</li><li><code>Epb</code>: Electronic Parking Brake (Elektrische Parkbremse).\n</li><li><code>Rsc</code>: Roll Stability Control (Kippschutz / Wankstabilitätsregelung).\n</li><li><code>Esc</code>: Electronic Stability Control (Fahrdynamik- und Giermomentenregelung).\n</li></ul>\n</li><li><strong>Vertikaldynamik &amp; Monitoring:</strong>\n<ul class=\"fig-list\"><li><code>Susp</code>: Suspension Control (Fahrwerk- und semiaktive/aktive Dämpferregelung).\n</li><li><code>TirePMon</code>: Tire Pressure Monitoring (Reifendruckkontrollsystem).\n</li></ul>\n</li><li><strong>Querdynamik &amp; Allradmanagement:</strong>\n<ul class=\"fig-list\"><li><code>DtTqDibtn</code>: Drive Train Torque Distribution (Antriebsmomentenverteilung / Torque Vectoring).\n</li><li><code>Steer</code>: Zentrale Lenkungsregelung (Electric Power Steering).\n</li><li><code>SteerVehStabyCtrl</code>: Steering Vehicle Stability Control (Fahrstabilitätsstützende Lenkeingriffe / Gegenlenkfunktion).\n</li><li><code>SteerDrvrAsscSys</code>: Steering Driver Assistance Systems (Fahrerassistenzlenkung, z. B. LKA/Spurhalteunterstützung).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne Kopplungen (Chassis-interne Assoziationen)</h5>\n<ul class=\"fig-list\"><li>Hierarchische Wirkkette der Längsdynamik: <code>CrsCtrlAndAcc</code> → <code>Vlc</code> → <code>Ssm</code> / <code>Rsc</code> → <code>Esc</code> sowie <code>Ssm</code> → <code>Epb</code> → <code>Esc</code>.\n</li><li>Modulare Bündelung der Querdynamik: <code>SteerVehStabyCtrl</code> und <code>SteerDrvrAsscSys</code> greifen additiv auf den Aktor-Pfad von <code>Steer</code> zu.\n</li></ul>\n<h5 class=\"fig-section-h5\">Externe Domänen &amp; Schnittstellenkanäle (1–26)</h5>\n<p class=\"fig-p\"><em>Ports: R-Port = Chassis Receiver Interface (grün), P-Port = Chassis Provider Interface (rot).</em></p>\n<ul class=\"fig-list\"><li><strong>Globale Broadcast-Schnittstellen (Body → alle Chassis-SW-Cs):</strong>\n<ul class=\"fig-list\"><li><code>Energy Management Status</code> (Bordnetzzustand, Powermode, Degradationsstufen).\n</li><li><code>System Startup/Setup</code> (Lifecycle-Koordination, Klemmenstatus / Wake-up).\n</li></ul>\n</li><li><strong>Numerierte Abhängigkeiten im Detail:</strong>\n<ul class=\"fig-list\"><li><code>1</code> (Powertrain → <code>CrsCtrlAndAcc</code>): R-Port; Ist-Geschwindigkeit, Getriebegang, Motorstatus.\n</li><li><code>2</code> (<code>CrsCtrlAndAcc</code> → P&amp;P Safety): P-Port; Zielobjektdaten, Verzögerungsanforderungen, Crash-Vorwarnung.\n</li><li><code>3</code> (<code>CrsCtrlAndAcc</code> ↔ HMI): Bidirektional; Fahrer-Setzgeschwindigkeiten, Tastenbedienung, Displayanzeigen (<em>gestrichelt: nicht im Master Table</em>).\n</li><li><code>4</code> (<code>Vlc</code> ↔ Powertrain): Bidirektional; Soll-Antriebsmomente/-begrenzungen vs. rückgemeldetes Istmoment.\n</li><li><code>5</code> (Body → <code>Ssm</code>): R-Port; Türkontakt-, Gurtschloss- und Klemmeninformationen.\n</li><li><code>6</code> (<code>Ssm</code> ↔ Powertrain): Bidirektional; Start/Stopp-Anforderung, Motorfreigabe.\n</li><li><code>7</code> (<code>Ssm</code> → HMI): P-Port; Status- und Fehlermeldungen der Sicherheitszustandsüberwachung.\n</li><li><code>8</code> (Powertrain → <code>Rsc</code>): R-Port; Rad- und Getriebemomente zur Wankmomentberechnung.\n</li><li><code>9</code> (<code>Esc</code> → Body): P-Port; Bremslichtaktivierung, Raddrehzahlsignale.\n</li><li><code>10</code> (<code>Esc</code> ↔ Powertrain): Bidirektional; ASR/MSR-Momenteneingriffe vs. Ist-Drehzahlen.\n</li><li><code>11</code> (<code>Esc</code> ↔ P&amp;P Safety): Bidirektional; Gierrate/Querbeschleunigung vs. Pre-Crash-Aktorauslösung.\n</li><li><code>12</code> (<code>Esc</code> ↔ HMI): Bidirektional; ESP-Taster (Deaktivierung/Sport) vs. Eingriffs-/Warnleuchte.\n</li><li><code>13</code> (Body → <code>Susp</code>): R-Port; Karosseriehöhensensoren, Beladungszustand, Türstatus.\n</li><li><code>14</code> (Powertrain → <code>Susp</code>): R-Port; Längsbeschleunigung, Ganginformation (Nickausgleich).\n</li><li><code>15</code> (<code>Susp</code> ↔ HMI): Bidirektional; Fahrwerksmodi (Komfort/Sport) vs. Niveaustatusanzeige.\n</li><li><code>16</code> (<code>DtTqDibtn</code> → Powertrain): P-Port; Rad- bzw. Achsmomenten-Stellbefehle (Differenzialsperren, Kupplungsansteuerung).\n</li><li><code>17</code> (<code>DtTqDibtn</code> → HMI): P-Port; Allrad-/Verteilungsstatus.\n</li><li><code>18</code> (Body → <code>TirePMon</code>): R-Port; Umgebungstemperatur, Klemmenstatus.\n</li><li><code>19</code> (Powertrain → <code>TirePMon</code>): R-Port; Raddrehzahlen (bei indirekten RDKS-Algorithmen).\n</li><li><code>20</code> (<code>TirePMon</code> ↔ HMI): Bidirektional; Reset-/Kalibrierbefehl vs. Druckwarnungen (<em>gestrichelt: nicht im Master Table</em>).\n</li><li><code>21</code> (<code>Steer</code> → Powertrain): P-Port; Lenkleistungsbedarf (Generator-/Bordnetzvorsteuerung).\n</li><li><code>22</code> (<code>Steer</code> ↔ HMI): Bidirektional; Lenkkraft-Modusauswahl vs. Warnmeldungen.\n</li><li><code>23</code> (<code>SteerVehStabyCtrl</code> ↔ HMI): Bidirektional; Stabilitätsunterstützung Ein/Aus vs. Eingriffsanzeige.\n</li><li><code>24</code> (<code>SteerDrvrAsscSys</code> ↔ HMI): Bidirektional; Spurführungsassistenz Ein/Aus, Haptik-Feedback vs. Status.\n</li><li><code>25</code> (<code>Steer</code> → Body): P-Port; Lenkradwinkel für dynamisches Kurvenlicht.\n</li><li><code>26</code> (<code>Epb</code> ↔ HMI): Bidirektional; Parkbremstaster vs. Kontrollleuchte/Zustandsrückmeldung (<em>gestrichelt: nicht im Master Table</em>).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Strukturmodell handelt, existieren keine expliziten UML-Lebenslinien. Die zugrundeliegenden Datenfluss- und Regelkreismuster sind:</p>\n<ul class=\"fig-list\"><li><strong>Kommunikationsparadigma:</strong> Asynchrone und zyklische <code>Sender-Receiver</code>-Kommunikation via VFB/RTE (<code>DataElements</code> ohne blockierende Client-Server-Semantik zur Gewährleistung harter Echtzeitfähigkeit).\n</li><li><strong>Arbitrierungs- und Override-Kaskade:</strong>\n<ol class=\"fig-list\"><li><em>Fahrer-/Assistenzanforderung:</em> <code>CrsCtrlAndAcc</code> generiert Beschleunigungs-/Verzögerungssollwert an <code>Vlc</code>.\n</li><li><em>Aktorkoordination:</em> <code>Vlc</code> arbitriert Anforderung gegen Antriebsgrenzen (<code>Powertrain</code>, Pfad 4) und Bremskapazität (<code>Ssm</code>/<code>Esc</code>).\n</li><li><em>Dynamischer Stabilitäts-Override:</em> Bei instabilem Fahrzustand (Übersteuern/Untersteuern) erzwingt <code>Esc</code> (Pfade 10/11) Vorrang vor <code>Vlc</code>/<code>Powertrain</code>, drosselt das Antriebsmoment und initiiert radindividuelle Bremseingriffe. Parallel generiert <code>SteerVehStabyCtrl</code> ein korrigierendes Lenkmoment über <code>Steer</code>.\n</li></ol>\n</li><li><strong>Systemzustandssteuerung:</strong> Moduswechsel im Body-Energiemanagement triggern via <code>Energy Management Status</code> Rückfallebenen (z. B. Deaktivierung von Komfort-Subfunktionen in <code>Susp</code> oder <code>CrsCtrlAndAcc</code> bei Unterspannung).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- &amp; Port-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Jede Verbindung entspricht im ARXML-Datenmodell einem <code>PortPrototype</code> (mit <code>SenderReceiverInterface</code>). \n</li><li>Die globalen Interfaces (<code>Energy Management Status</code>, <code>System Startup/Setup</code>) müssen in jedem Chassis-SW-C-Descriptor als erforderlicher R-Port instanziiert und mit den entsprechenden BSW-Mode-Managern (<code>BswM</code>) oder Body-Applikationen verbunden werden.\n</li></ul>\n</li><li><strong>Master-Table-Status (Gestrichelte Linien / Boxen):</strong>\n<ul class=\"fig-list\"><li>Schnittstellen 3, 20 und 26 sind in Release R4.0.3 noch nicht vollständig im <em>AUTOSAR Application Interfaces Master Table</em> normiert. Für diese Kommunikationspfade müssen projektspezifische Interface-Definitionen bzw. OEM-spezifische Datentypen definiert werden.\n</li></ul>\n</li><li><strong>Echtzeit- und Latenzanforderungen (Bus-Mapping):</strong>\n<ul class=\"fig-list\"><li>Regelkreise zwischen <code>Vlc</code>, <code>Esc</code>, <code>Steer</code> und <code>Powertrain</code> erfordern Zykluszeiten von ≤ 10\\,ms.\n</li><li>Werden diese SW-Cs auf verschiedene ECUs verteilt, erfordert das Bus-Mapping deterministische Frame-Übertragungen (CAN-FD, FlexRay oder Ethernet mit TSN) sowie zwingend die Konfiguration von E2E-Schutzprofilen (<code>E2E Library</code>, ASIL-D-Konformität nach ISO 26262 für Pfade 2, 4, 10, 11).\n</li></ul>\n</li><li><strong>Diagnose- und Fehlermanagement (Dem/Det):</strong>\n<ul class=\"fig-list\"><li>Ausfall von Receiver-Signalen (z. B. Timeout auf Pfad 1, 14 oder 19) muss über standardisierte FIM-Inhibition-Ketten (<code>FunctionInhibitionManager</code>) zur kontrollierten Funktionsabschaltung (Graceful Degradation) und zum Setzen relevanter DTCs im <code>Dem</code> führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-b17eda362c999ef7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Komponentendiagramm / VFB-Architekturübersicht (Virtual Function Bus) auf Ebene der AUTOSAR-Applikationsschicht (<code>Application Layer</code>).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der domänenübergreifenden Schnittstellenbeziehungen (<em>Inter Domain Dependencies</em>) zwischen den Software-Komponenten (<code>ApplicationSwComponentType</code>) der Fahrwerk-Domäne (<em>Chassis Domain</em>) und externen Fahrzeugdomänen (<em>Powertrain</em>, <em>Body</em>, <em>HMI</em>, <em>P&amp;P Safety</em>).\n</li><li><strong>Funktionale Einordnung:</strong> Dient als Allokations- und Integrationsreferenz zur Entkopplung logischer Steuerungsfunktionen (Längs-, Quer- und Vertikaldynamik) von der physischen Steuergeräte-Topologie (z. B. Bremsen-, Lenkungs- oder Dämpfer-ECUs).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Chassis Domain Software-Komponenten (<code>SW-C</code>)</h5>\n<ul class=\"fig-list\"><li><strong>Längsdynamik &amp; Verzögerung:</strong>\n<ul class=\"fig-list\"><li><code>CrsCrtlAndAcc</code>: Cruise Control &amp; Adaptive Cruise Control (Geschwindigkeits- und Abstandsregelung; im Diagramm mit Schreibweise <code>CrsCrtl</code>).\n</li><li><code>Vlc</code>: Vehicle Longitudinal Control (Längsdynamikkoordinator / Traktions- und Bremsarbitrierung).\n</li><li><code>Ssm</code>: Secondary Slip Management / Safe State Management (Sollwertvorgabe und Sicherheitsüberwachung).\n</li><li><code>Epb</code>: Electronic Parking Brake (Elektrische Parkbremse).\n</li><li><code>Rsc</code>: Roll Stability Control (Kippschutz / Wankstabilitätsregelung).\n</li><li><code>Esc</code>: Electronic Stability Control (Fahrdynamik- und Giermomentenregelung).\n</li></ul>\n</li><li><strong>Vertikaldynamik &amp; Monitoring:</strong>\n<ul class=\"fig-list\"><li><code>Susp</code>: Suspension Control (Fahrwerk- und semiaktive/aktive Dämpferregelung).\n</li><li><code>TirePMon</code>: Tire Pressure Monitoring (Reifendruckkontrollsystem).\n</li></ul>\n</li><li><strong>Querdynamik &amp; Allradmanagement:</strong>\n<ul class=\"fig-list\"><li><code>DtTqDistbn</code>: Drive Train Torque Distribution (Antriebsmomentenverteilung / Torque Vectoring; Schreibweise korrigiert von <code>DtTqDibtn</code>).\n</li><li><code>Steer</code>: Zentrale Lenkungsregelung (Electric Power Steering).\n</li><li><code>SteerVehStabyCtrl</code>: Steering Vehicle Stability Control (Fahrstabilitätsstützende Lenkeingriffe / Gegenlenkfunktion).\n</li><li><code>SteerDrvrAsscSys</code>: Steering Driver Assistance Systems (Fahrerassistenzlenkung, z. B. LKA/Spurhalteunterstützung).\n</li></ul>\n</li><li><strong>Parkassistenz:</strong>\n<ul class=\"fig-list\"><li><code>PrkgAid</code>: Parking Aid (Parksensorik und Einparkassistenz; neu ergänzt).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne Kopplungen (Chassis-interne Assoziationen)</h5>\n<ul class=\"fig-list\"><li>Hierarchische Wirkkette der Längsdynamik: <code>CrsCrtlAndAcc</code> → <code>Vlc</code> → <code>Ssm</code> / <code>Rsc</code> → <code>Esc</code> sowie <code>Ssm</code> → <code>Epb</code> → <code>Esc</code>.\n</li><li>Modulare Bündelung der Querdynamik: <code>SteerVehStabyCtrl</code> und <code>SteerDrvrAsscSys</code> greifen additiv auf den Aktor-Pfad von <code>Steer</code> zu.\n</li></ul>\n<h5 class=\"fig-section-h5\">Externe Domänen &amp; Schnittstellenkanäle (1–27)</h5>\n<p class=\"fig-p\"><em>Ports: R-Port = Chassis Receiver Interface (grün), P-Port = Chassis Provider Interface (rot).</em></p>\n<ul class=\"fig-list\"><li><strong>Globale Broadcast-Schnittstellen (Body → alle Chassis-SW-Cs):</strong>\n<ul class=\"fig-list\"><li><code>Energy Management Status</code> (Bordnetzzustand, Powermode, Degradationsstufen).\n</li><li><code>System Startup/Setup</code> (Lifecycle-Koordination, Klemmenstatus / Wake-up).\n</li></ul>\n</li><li><strong>Numerierte Abhängigkeiten im Detail:</strong>\n<ul class=\"fig-list\"><li><code>1</code> (Powertrain → <code>CrsCrtlAndAcc</code>): R-Port; Ist-Geschwindigkeit, Getriebegang, Motorstatus.\n</li><li><code>2</code> (<code>CrsCrtlAndAcc</code> → P&amp;P Safety): P-Port; Zielobjektdaten, Verzögerungsanforderungen, Crash-Vorwarnung (<em>gestrichelt: nicht im Master Table</em>).\n</li><li><code>3</code> (<code>CrsCrtlAndAcc</code> ↔ HMI): Bidirektional; Fahrer-Setzgeschwindigkeiten, Tastenbedienung, Displayanzeigen (<em>gestrichelt: nicht im Master Table</em>).\n</li><li><code>4</code> (<code>Vlc</code> ↔ Powertrain): Bidirektional; Soll-Antriebsmomente/-begrenzungen vs. rückgemeldetes Istmoment.\n</li><li><code>5</code> (Body → <code>Ssm</code>): R-Port; Türkontakt-, Gurtschloss- und Klemmeninformationen.\n</li><li><code>6</code> (<code>Ssm</code> ↔ Powertrain): Bidirektional; Start/Stopp-Anforderung, Motorfreigabe.\n</li><li><code>7</code> (<code>Ssm</code> → HMI): P-Port; Status- und Fehlermeldungen der Sicherheitszustandsüberwachung.\n</li><li><code>8</code> (Powertrain → <code>Rsc</code>): R-Port; Rad- und Getriebemomente zur Wankmomentberechnung.\n</li><li><code>9</code> (<code>Esc</code> → Body): P-Port; Bremslichtaktivierung, Raddrehzahlsignale.\n</li><li><code>10</code> (<code>Esc</code> ↔ Powertrain): Bidirektional; ASR/MSR-Momenteneingriffe vs. Ist-Drehzahlen.\n</li><li><code>11</code> (<code>Esc</code> ↔ P&amp;P Safety): Bidirektional; Gierrate/Querbeschleunigung vs. Pre-Crash-Aktorauslösung.\n</li><li><code>12</code> (<code>Esc</code> ↔ HMI): Bidirektional; ESP-Taster (Deaktivierung/Sport) vs. Eingriffs-/Warnleuchte.\n</li><li><code>13</code> (Body → <code>Susp</code>): R-Port; Karosseriehöhensensoren, Beladungszustand, Türstatus.\n</li><li><code>14</code> (Powertrain → <code>Susp</code>): R-Port; Längsbeschleunigung, Ganginformation (Nickausgleich).\n</li><li><code>15</code> (<code>Susp</code> ↔ HMI): Bidirektional; Fahrwerksmodi (Komfort/Sport) vs. Niveaustatusanzeige.\n</li><li><code>16</code> (<code>DtTqDistbn</code> → Powertrain): P-Port; Rad- bzw. Achsmomenten-Stellbefehle (Differenzialsperren, Kupplungsansteuerung).\n</li><li><code>17</code> (<code>DtTqDistbn</code> → HMI): P-Port; Allrad-/Verteilungsstatus.\n</li><li><code>18</code> (Body → <code>TirePMon</code>): R-Port; Umgebungstemperatur, Klemmenstatus.\n</li><li><code>19</code> (Powertrain → <code>TirePMon</code>): R-Port; Raddrehzahlen (bei indirekten RDKS-Algorithmen).\n</li><li><code>20</code> (<code>TirePMon</code> ↔ HMI): Bidirektional; Reset-/Kalibrierbefehl vs. Druckwarnungen (<em>gestrichelt: nicht im Master Table</em>).\n</li><li><code>21</code> (<code>Steer</code> → Powertrain): P-Port; Lenkleistungsbedarf (Generator-/Bordnetzvorsteuerung).\n</li><li><code>22</code> (<code>Steer</code> ↔ HMI): Bidirektional; Lenkkraft-Modusauswahl vs. Warnmeldungen.\n</li><li><code>23</code> (<code>SteerVehStabyCtrl</code> ↔ HMI): Bidirektional; Stabilitätsunterstützung Ein/Aus vs. Eingriffsanzeige.\n</li><li><code>24</code> (<code>SteerDrvrAsscSys</code> ↔ HMI): Bidirektional; Spurführungsassistenz Ein/Aus, Haptik-Feedback vs. Status.\n</li><li><code>25</code> (Mehrfachbelegung im Diagramm):\n<ul class=\"fig-list\"><li><code>Steer</code> → Body: P-Port; Lenkradwinkel für dynamisches Kurvenlicht.\n</li><li>Body → <code>PrkgAid</code>: R-Port; Ultraschallsensor- und Stoßfängerdaten, Rückwärtsgangstatus.\n</li></ul>\n</li><li><code>26</code> (Mehrfachbelegung im Diagramm):\n<ul class=\"fig-list\"><li><code>Epb</code> ↔ HMI: Bidirektional; Parkbremstaster vs. Kontrollleuchte/Zustandsrückmeldung (<em>gestrichelt: nicht im Master Table</em>).\n</li><li>Powertrain → <code>PrkgAid</code>: R-Port; Raddrehzahl-, Geschwindigkeits- und Getriebeinformationen.\n</li></ul>\n</li><li><code>27</code> (<code>PrkgAid</code> ↔ HMI): Bidirektional; Parkhilfetaster (Aktivierung/Deaktivierung) vs. akustische und optische Distanzanzeige.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Strukturmodell handelt, existieren keine expliziten UML-Lebenslinien. Die zugrundeliegenden Datenfluss- und Regelkreismuster sind:</p>\n<ul class=\"fig-list\"><li><strong>Kommunikationsparadigma:</strong> Asynchrone und zyklische <code>Sender-Receiver</code>-Kommunikation via VFB/RTE (<code>DataElements</code> ohne blockierende Client-Server-Semantik zur Gewährleistung harter Echtzeitfähigkeit).\n</li><li><strong>Arbitrierungs- und Override-Kaskade:</strong>\n<ol class=\"fig-list\"><li><em>Fahrer-/Assistenzanforderung:</em> <code>CrsCtrlAndAcc</code> generiert Beschleunigungs-/Verzögerungssollwert an <code>Vlc</code>.\n</li><li><em>Aktorkoordination:</em> <code>Vlc</code> arbitriert Anforderung gegen Antriebsgrenzen (<code>Powertrain</code>, Pfad 4) und Bremskapazität (<code>Ssm</code>/<code>Esc</code>).\n</li><li><em>Dynamischer Stabilitäts-Override:</em> Bei instabilem Fahrzustand (Übersteuern/Untersteuern) erzwingt <code>Esc</code> (Pfade 10/11) Vorrang vor <code>Vlc</code>/<code>Powertrain</code>, drosselt das Antriebsmoment und initiiert radindividuelle Bremseingriffe. Parallel generiert <code>SteerVehStabyCtrl</code> ein korrigierendes Lenkmoment über <code>Steer</code>.\n</li></ol>\n</li><li><strong>Systemzustandssteuerung:</strong> Moduswechsel im Body-Energiemanagement triggern via <code>Energy Management Status</code> Rückfallebenen (z. B. Deaktivierung von Komfort-Subfunktionen in <code>Susp</code> oder <code>CrsCtrlAndAcc</code> bei Unterspannung).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- &amp; Port-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Jede Verbindung entspricht im ARXML-Datenmodell einem <code>PortPrototype</code> (mit <code>SenderReceiverInterface</code>). \n</li><li>Die globalen Interfaces (<code>Energy Management Status</code>, <code>System Startup/Setup</code>) müssen in jedem Chassis-SW-C-Descriptor als erforderlicher R-Port instanziiert und mit den entsprechenden BSW-Mode-Managern (<code>BswM</code>) oder Body-Applikationen verbunden werden.\n</li></ul>\n</li><li><strong>Master-Table-Status (Gestrichelte Linien / Boxen):</strong>\n<ul class=\"fig-list\"><li>Schnittstellen 3, 20 und 26 sind in Release R4.0.3 noch nicht vollständig im <em>AUTOSAR Application Interfaces Master Table</em> normiert. Für diese Kommunikationspfade müssen projektspezifische Interface-Definitionen bzw. OEM-spezifische Datentypen definiert werden.\n</li></ul>\n</li><li><strong>Echtzeit- und Latenzanforderungen (Bus-Mapping):</strong>\n<ul class=\"fig-list\"><li>Regelkreise zwischen <code>Vlc</code>, <code>Esc</code>, <code>Steer</code> und <code>Powertrain</code> erfordern Zykluszeiten von ≤ 10\\,ms.\n</li><li>Werden diese SW-Cs auf verschiedene ECUs verteilt, erfordert das Bus-Mapping deterministische Frame-Übertragungen (CAN-FD, FlexRay oder Ethernet mit TSN) sowie zwingend die Konfiguration von E2E-Schutzprofilen (<code>E2E Library</code>, ASIL-D-Konformität nach ISO 26262 für Pfade 2, 4, 10, 11).\n</li></ul>\n</li><li><strong>Diagnose- und Fehlermanagement (Dem/Det):</strong>\n<ul class=\"fig-list\"><li>Ausfall von Receiver-Signalen (z. B. Timeout auf Pfad 1, 14 oder 19) muss über standardisierte FIM-Inhibition-Ketten (<code>FunctionInhibitionManager</code>) zur kontrollierten Funktionsabschaltung (Graceful Degradation) und zum Setzen relevanter DTCs im <code>Dem</code> führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-86fbe7eaf98ad092", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Komponentendiagramm / VFB-Architekturübersicht (Virtual Function Bus) auf Ebene der AUTOSAR-Applikationsschicht (<code>Application Layer</code>).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der domänenübergreifenden Schnittstellenbeziehungen (<em>Inter Domain Dependencies</em>) zwischen den Software-Komponenten (<code>ApplicationSwComponentType</code>) der Fahrwerk-Domäne (<em>Chassis Domain</em>) und externen Fahrzeugdomänen (<em>Powertrain</em>, <em>Body</em>, <em>HMI</em>, <em>P&amp;P Safety</em>).\n</li><li><strong>Funktionale Einordnung:</strong> Dient als Allokations- und Integrationsreferenz zur Entkopplung logischer Steuerungsfunktionen (Längs-, Quer- und Vertikaldynamik) von der physischen Steuergeräte-Topologie (z. B. Bremsen-, Lenkungs- oder Dämpfer-ECUs).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Chassis Domain Software-Komponenten (<code>SW-C</code>)</h5>\n<ul class=\"fig-list\"><li><strong>Längsdynamik &amp; Verzögerung:</strong>\n<ul class=\"fig-list\"><li><code>CrsCrtlAndAcc</code>: Cruise Control &amp; Adaptive Cruise Control (Geschwindigkeits- und Abstandsregelung; im Diagramm mit Schreibweise <code>CrsCrtl</code>).\n</li><li><code>Vlc</code>: Vehicle Longitudinal Control (Längsdynamikkoordinator / Traktions- und Bremsarbitrierung).\n</li><li><code>Ssm</code>: Secondary Slip Management / Safe State Management (Sollwertvorgabe und Sicherheitsüberwachung).\n</li><li><code>Epb</code>: Electronic Parking Brake (Elektrische Parkbremse).\n</li><li><code>Rsc</code>: Roll Stability Control (Kippschutz / Wankstabilitätsregelung).\n</li><li><code>Esc</code>: Electronic Stability Control (Fahrdynamik- und Giermomentenregelung).\n</li></ul>\n</li><li><strong>Vertikaldynamik &amp; Monitoring:</strong>\n<ul class=\"fig-list\"><li><code>Susp</code>: Suspension Control (Fahrwerk- und semiaktive/aktive Dämpferregelung).\n</li><li><code>TirePMon</code>: Tire Pressure Monitoring (Reifendruckkontrollsystem).\n</li></ul>\n</li><li><strong>Querdynamik &amp; Allradmanagement:</strong>\n<ul class=\"fig-list\"><li><code>DtTqDistbn</code>: Drive Train Torque Distribution (Antriebsmomentenverteilung / Torque Vectoring; Schreibweise korrigiert von <code>DtTqDibtn</code>).\n</li><li><code>Steer</code>: Zentrale Lenkungsregelung (Electric Power Steering).\n</li><li><code>SteerVehStabyCtrl</code>: Steering Vehicle Stability Control (Fahrstabilitätsstützende Lenkeingriffe / Gegenlenkfunktion).\n</li><li><code>SteerDrvrAsscSys</code>: Steering Driver Assistance Systems (Fahrerassistenzlenkung, z. B. LKA/Spurhalteunterstützung).\n</li></ul>\n</li><li><strong>Parkassistenz:</strong>\n<ul class=\"fig-list\"><li><code>PrkgAid</code>: Parking Aid (Parksensorik und Einparkassistenz; neu ergänzt).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne Kopplungen (Chassis-interne Assoziationen)</h5>\n<ul class=\"fig-list\"><li>Hierarchische Wirkkette der Längsdynamik: <code>CrsCrtlAndAcc</code> → <code>Vlc</code> → <code>Ssm</code> / <code>Rsc</code> → <code>Esc</code> sowie <code>Ssm</code> → <code>Epb</code> → <code>Esc</code>.\n</li><li>Modulare Bündelung der Querdynamik: <code>SteerVehStabyCtrl</code> und <code>SteerDrvrAsscSys</code> greifen additiv auf den Aktor-Pfad von <code>Steer</code> zu.\n</li></ul>\n<h5 class=\"fig-section-h5\">Externe Domänen &amp; Schnittstellenkanäle (1–27)</h5>\n<p class=\"fig-p\"><em>Ports: R-Port = Chassis Receiver Interface (grün), P-Port = Chassis Provider Interface (rot).</em></p>\n<ul class=\"fig-list\"><li><strong>Globale Broadcast-Schnittstellen (Body → alle Chassis-SW-Cs):</strong>\n<ul class=\"fig-list\"><li><code>Energy Management Status</code> (Bordnetzzustand, Powermode, Degradationsstufen).\n</li><li><code>System Startup/Setup</code> (Lifecycle-Koordination, Klemmenstatus / Wake-up).\n</li></ul>\n</li><li><strong>Numerierte Abhängigkeiten im Detail:</strong>\n<ul class=\"fig-list\"><li><code>1</code> (Powertrain → <code>CrsCrtlAndAcc</code>): R-Port; Ist-Geschwindigkeit, Getriebegang, Motorstatus.\n</li><li><code>2</code> (<code>CrsCrtlAndAcc</code> → P&amp;P Safety): P-Port; Zielobjektdaten, Verzögerungsanforderungen, Crash-Vorwarnung (<em>gestrichelt: nicht im Master Table</em>).\n</li><li><code>3</code> (<code>CrsCrtlAndAcc</code> ↔ HMI): Bidirektional; Fahrer-Setzgeschwindigkeiten, Tastenbedienung, Displayanzeigen (<em>gestrichelt: nicht im Master Table</em>).\n</li><li><code>4</code> (<code>Vlc</code> ↔ Powertrain): Bidirektional; Soll-Antriebsmomente/-begrenzungen vs. rückgemeldetes Istmoment.\n</li><li><code>5</code> (Body → <code>Ssm</code>): R-Port; Türkontakt-, Gurtschloss- und Klemmeninformationen.\n</li><li><code>6</code> (<code>Ssm</code> ↔ Powertrain): Bidirektional; Start/Stopp-Anforderung, Motorfreigabe.\n</li><li><code>7</code> (<code>Ssm</code> → HMI): P-Port; Status- und Fehlermeldungen der Sicherheitszustandsüberwachung.\n</li><li><code>8</code> (Powertrain → <code>Rsc</code>): R-Port; Rad- und Getriebemomente zur Wankmomentberechnung.\n</li><li><code>9</code> (<code>Esc</code> → Body): P-Port; Bremslichtaktivierung, Raddrehzahlsignale.\n</li><li><code>10</code> (<code>Esc</code> ↔ Powertrain): Bidirektional; ASR/MSR-Momenteneingriffe vs. Ist-Drehzahlen.\n</li><li><code>11</code> (<code>Esc</code> ↔ P&amp;P Safety): Bidirektional; Gierrate/Querbeschleunigung vs. Pre-Crash-Aktorauslösung.\n</li><li><code>12</code> (<code>Esc</code> ↔ HMI): Bidirektional; ESP-Taster (Deaktivierung/Sport) vs. Eingriffs-/Warnleuchte.\n</li><li><code>13</code> (Body → <code>Susp</code>): R-Port; Karosseriehöhensensoren, Beladungszustand, Türstatus.\n</li><li><code>14</code> (Powertrain → <code>Susp</code>): R-Port; Längsbeschleunigung, Ganginformation (Nickausgleich).\n</li><li><code>15</code> (<code>Susp</code> ↔ HMI): Bidirektional; Fahrwerksmodi (Komfort/Sport) vs. Niveaustatusanzeige.\n</li><li><code>16</code> (<code>DtTqDistbn</code> → Powertrain): P-Port; Rad- bzw. Achsmomenten-Stellbefehle (Differenzialsperren, Kupplungsansteuerung).\n</li><li><code>17</code> (<code>DtTqDistbn</code> → HMI): P-Port; Allrad-/Verteilungsstatus.\n</li><li><code>18</code> (Body → <code>TirePMon</code>): R-Port; Umgebungstemperatur, Klemmenstatus.\n</li><li><code>19</code> (Powertrain → <code>TirePMon</code>): R-Port; Raddrehzahlen (bei indirekten RDKS-Algorithmen).\n</li><li><code>20</code> (<code>TirePMon</code> ↔ HMI): Bidirektional; Reset-/Kalibrierbefehl vs. Druckwarnungen (<em>gestrichelt: nicht im Master Table</em>).\n</li><li><code>21</code> (<code>Steer</code> → Powertrain): P-Port; Lenkleistungsbedarf (Generator-/Bordnetzvorsteuerung).\n</li><li><code>22</code> (<code>Steer</code> ↔ HMI): Bidirektional; Lenkkraft-Modusauswahl vs. Warnmeldungen.\n</li><li><code>23</code> (<code>SteerVehStabyCtrl</code> ↔ HMI): Bidirektional; Stabilitätsunterstützung Ein/Aus vs. Eingriffsanzeige.\n</li><li><code>24</code> (<code>SteerDrvrAsscSys</code> ↔ HMI): Bidirektional; Spurführungsassistenz Ein/Aus, Haptik-Feedback vs. Status.\n</li><li><code>25</code> (Mehrfachbelegung im Diagramm):\n<ul class=\"fig-list\"><li><code>Steer</code> → Body: P-Port; Lenkradwinkel für dynamisches Kurvenlicht.\n</li><li>Body → <code>PrkgAid</code>: R-Port; Ultraschallsensor- und Stoßfängerdaten, Rückwärtsgangstatus.\n</li></ul>\n</li><li><code>26</code> (Mehrfachbelegung im Diagramm):\n<ul class=\"fig-list\"><li><code>Epb</code> ↔ HMI: Bidirektional; Parkbremstaster vs. Kontrollleuchte/Zustandsrückmeldung (<em>gestrichelt: nicht im Master Table</em>).\n</li><li>Powertrain → <code>PrkgAid</code>: R-Port; Raddrehzahl-, Geschwindigkeits- und Getriebeinformationen.\n</li></ul>\n</li><li><code>27</code> (<code>PrkgAid</code> ↔ HMI): Bidirektional; Parkhilfetaster (Aktivierung/Deaktivierung) vs. akustische und optische Distanzanzeige.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Strukturmodell handelt, existieren keine expliziten UML-Lebenslinien. Die zugrundeliegenden Datenfluss- und Regelkreismuster sind:</p>\n<ul class=\"fig-list\"><li><strong>Kommunikationsparadigma:</strong> Asynchrone und zyklische <code>Sender-Receiver</code>-Kommunikation via VFB/RTE (<code>DataElements</code> ohne blockierende Client-Server-Semantik zur Gewährleistung harter Echtzeitfähigkeit).\n</li><li><strong>Arbitrierungs- und Override-Kaskade:</strong>\n<ol class=\"fig-list\"><li><em>Fahrer-/Assistenzanforderung:</em> <code>CrsCtrlAndAcc</code> generiert Beschleunigungs-/Verzögerungssollwert an <code>Vlc</code>.\n</li><li><em>Aktorkoordination:</em> <code>Vlc</code> arbitriert Anforderung gegen Antriebsgrenzen (<code>Powertrain</code>, Pfad 4) und Bremskapazität (<code>Ssm</code>/<code>Esc</code>).\n</li><li><em>Dynamischer Stabilitäts-Override:</em> Bei instabilem Fahrzustand (Übersteuern/Untersteuern) erzwingt <code>Esc</code> (Pfade 10/11) Vorrang vor <code>Vlc</code>/<code>Powertrain</code>, drosselt das Antriebsmoment und initiiert radindividuelle Bremseingriffe. Parallel generiert <code>SteerVehStabyCtrl</code> ein korrigierendes Lenkmoment über <code>Steer</code>.\n</li></ol>\n</li><li><strong>Systemzustandssteuerung:</strong> Moduswechsel im Body-Energiemanagement triggern via <code>Energy Management Status</code> Rückfallebenen (z. B. Deaktivierung von Komfort-Subfunktionen in <code>Susp</code> oder <code>CrsCtrlAndAcc</code> bei Unterspannung).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- &amp; Port-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Jede Verbindung entspricht im ARXML-Datenmodell einem <code>PortPrototype</code> (mit <code>SenderReceiverInterface</code>). \n</li><li>Die globalen Interfaces (<code>Energy Management Status</code>, <code>System Startup/Setup</code>) müssen in jedem Chassis-SW-C-Descriptor als erforderlicher R-Port instanziiert und mit den entsprechenden BSW-Mode-Managern (<code>BswM</code>) oder Body-Applikationen verbunden werden.\n</li></ul>\n</li><li><strong>Master-Table-Status (Gestrichelte Linien / Boxen):</strong>\n<ul class=\"fig-list\"><li>Schnittstellen 3, 20 und 26 sind in Release R4.0.3 noch nicht vollständig im <em>AUTOSAR Application Interfaces Master Table</em> normiert. Für diese Kommunikationspfade müssen projektspezifische Interface-Definitionen bzw. OEM-spezifische Datentypen definiert werden.\n</li></ul>\n</li><li><strong>Echtzeit- und Latenzanforderungen (Bus-Mapping):</strong>\n<ul class=\"fig-list\"><li>Regelkreise zwischen <code>Vlc</code>, <code>Esc</code>, <code>Steer</code> und <code>Powertrain</code> erfordern Zykluszeiten von ≤ 10\\,ms.\n</li><li>Werden diese SW-Cs auf verschiedene ECUs verteilt, erfordert das Bus-Mapping deterministische Frame-Übertragungen (CAN-FD, FlexRay oder Ethernet mit TSN) sowie zwingend die Konfiguration von E2E-Schutzprofilen (<code>E2E Library</code>, ASIL-D-Konformität nach ISO 26262 für Pfade 2, 4, 10, 11).\n</li></ul>\n</li><li><strong>Diagnose- und Fehlermanagement (Dem/Det):</strong>\n<ul class=\"fig-list\"><li>Ausfall von Receiver-Signalen (z. B. Timeout auf Pfad 1, 14 oder 19) muss über standardisierte FIM-Inhibition-Ketten (<code>FunctionInhibitionManager</code>) zur kontrollierten Funktionsabschaltung (Graceful Degradation) und zum Setzen relevanter DTCs im <code>Dem</code> führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-45135d2fddb2d9d3", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Logisches Komponentendiagramm / VFB-Architekturübersicht (Virtual Function Bus) auf Ebene der AUTOSAR-Applikationsschicht (<code>Application Layer</code>).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der domänenübergreifenden Schnittstellenbeziehungen (<em>Inter Domain Dependencies</em>) zwischen den Software-Komponenten (<code>ApplicationSwComponentType</code>) der Fahrwerk-Domäne (<em>Chassis Domain</em>) und externen Fahrzeugdomänen (<em>Powertrain</em>, <em>Body</em>, <em>HMI</em>, <em>P&amp;P Safety</em>).\n</li><li><strong>Funktionale Einordnung:</strong> Dient als Allokations- und Integrationsreferenz zur Entkopplung logischer Steuerungsfunktionen (Längs-, Quer- und Vertikaldynamik) von der physischen Steuergeräte-Topologie (z. B. Bremsen-, Lenkungs- oder Dämpfer-ECUs).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Chassis Domain Software-Komponenten (<code>SW-C</code>)</h5>\n<ul class=\"fig-list\"><li><strong>Längsdynamik &amp; Verzögerung:</strong>\n<ul class=\"fig-list\"><li><code>CrsCrtlAndAcc</code>: Cruise Control &amp; Adaptive Cruise Control (Geschwindigkeits- und Abstandsregelung; im Diagramm mit Schreibweise <code>CrsCrtl</code>).\n</li><li><code>Vlc</code>: Vehicle Longitudinal Control (Längsdynamikkoordinator / Traktions- und Bremsarbitrierung).\n</li><li><code>Ssm</code>: Secondary Slip Management / Safe State Management (Sollwertvorgabe und Sicherheitsüberwachung).\n</li><li><code>Epb</code>: Electronic Parking Brake (Elektrische Parkbremse).\n</li><li><code>Rsc</code>: Roll Stability Control (Kippschutz / Wankstabilitätsregelung).\n</li><li><code>Esc</code>: Electronic Stability Control (Fahrdynamik- und Giermomentenregelung).\n</li></ul>\n</li><li><strong>Vertikaldynamik &amp; Monitoring:</strong>\n<ul class=\"fig-list\"><li><code>Susp</code>: Suspension Control (Fahrwerk- und semiaktive/aktive Dämpferregelung).\n</li><li><code>TirePMon</code>: Tire Pressure Monitoring (Reifendruckkontrollsystem).\n</li></ul>\n</li><li><strong>Querdynamik &amp; Allradmanagement:</strong>\n<ul class=\"fig-list\"><li><code>DtTqDistbn</code>: Drive Train Torque Distribution (Antriebsmomentenverteilung / Torque Vectoring; Schreibweise korrigiert von <code>DtTqDibtn</code>).\n</li><li><code>Steer</code>: Zentrale Lenkungsregelung (Electric Power Steering).\n</li><li><code>SteerVehStabyCtrl</code>: Steering Vehicle Stability Control (Fahrstabilitätsstützende Lenkeingriffe / Gegenlenkfunktion).\n</li><li><code>SteerDrvrAsscSys</code>: Steering Driver Assistance Systems (Fahrerassistenzlenkung, z. B. LKA/Spurhalteunterstützung).\n</li></ul>\n</li><li><strong>Parkassistenz:</strong>\n<ul class=\"fig-list\"><li><code>PrkgAid</code>: Parking Aid (Parksensorik und Einparkassistenz; neu ergänzt).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne Kopplungen (Chassis-interne Assoziationen)</h5>\n<ul class=\"fig-list\"><li>Hierarchische Wirkkette der Längsdynamik: <code>CrsCrtlAndAcc</code> → <code>Vlc</code> → <code>Ssm</code> / <code>Rsc</code> → <code>Esc</code> sowie <code>Ssm</code> → <code>Epb</code> → <code>Esc</code>.\n</li><li>Modulare Bündelung der Querdynamik: <code>SteerVehStabyCtrl</code> und <code>SteerDrvrAsscSys</code> greifen additiv auf den Aktor-Pfad von <code>Steer</code> zu.\n</li></ul>\n<h5 class=\"fig-section-h5\">Externe Domänen &amp; Schnittstellenkanäle (1–27)</h5>\n<p class=\"fig-p\"><em>Ports: R-Port = Chassis Receiver Interface (grün), P-Port = Chassis Provider Interface (rot).</em></p>\n<ul class=\"fig-list\"><li><strong>Globale Broadcast-Schnittstellen (Body → alle Chassis-SW-Cs):</strong>\n<ul class=\"fig-list\"><li><code>Energy Management Status</code> (Bordnetzzustand, Powermode, Degradationsstufen).\n</li><li><code>System Startup/Setup</code> (Lifecycle-Koordination, Klemmenstatus / Wake-up).\n</li></ul>\n</li><li><strong>Numerierte Abhängigkeiten im Detail:</strong>\n<ul class=\"fig-list\"><li><code>1</code> (Powertrain → <code>CrsCrtlAndAcc</code>): R-Port; Ist-Geschwindigkeit, Getriebegang, Motorstatus.\n</li><li><code>2</code> (<code>CrsCrtlAndAcc</code> → P&amp;P Safety): P-Port; Zielobjektdaten, Verzögerungsanforderungen, Crash-Vorwarnung (<em>gestrichelt: nicht im Master Table</em>).\n</li><li><code>3</code> (<code>CrsCrtlAndAcc</code> ↔ HMI): Bidirektional; Fahrer-Setzgeschwindigkeiten, Tastenbedienung, Displayanzeigen (<em>gestrichelt: nicht im Master Table</em>).\n</li><li><code>4</code> (<code>Vlc</code> ↔ Powertrain): Bidirektional; Soll-Antriebsmomente/-begrenzungen vs. rückgemeldetes Istmoment.\n</li><li><code>5</code> (Body → <code>Ssm</code>): R-Port; Türkontakt-, Gurtschloss- und Klemmeninformationen.\n</li><li><code>6</code> (<code>Ssm</code> ↔ Powertrain): Bidirektional; Start/Stopp-Anforderung, Motorfreigabe.\n</li><li><code>7</code> (<code>Ssm</code> → HMI): P-Port; Status- und Fehlermeldungen der Sicherheitszustandsüberwachung.\n</li><li><code>8</code> (Powertrain → <code>Rsc</code>): R-Port; Rad- und Getriebemomente zur Wankmomentberechnung.\n</li><li><code>9</code> (<code>Esc</code> → Body): P-Port; Bremslichtaktivierung, Raddrehzahlsignale.\n</li><li><code>10</code> (<code>Esc</code> ↔ Powertrain): Bidirektional; ASR/MSR-Momenteneingriffe vs. Ist-Drehzahlen.\n</li><li><code>11</code> (<code>Esc</code> ↔ P&amp;P Safety): Bidirektional; Gierrate/Querbeschleunigung vs. Pre-Crash-Aktorauslösung.\n</li><li><code>12</code> (<code>Esc</code> ↔ HMI): Bidirektional; ESP-Taster (Deaktivierung/Sport) vs. Eingriffs-/Warnleuchte.\n</li><li><code>13</code> (Body → <code>Susp</code>): R-Port; Karosseriehöhensensoren, Beladungszustand, Türstatus.\n</li><li><code>14</code> (Powertrain → <code>Susp</code>): R-Port; Längsbeschleunigung, Ganginformation (Nickausgleich).\n</li><li><code>15</code> (<code>Susp</code> ↔ HMI): Bidirektional; Fahrwerksmodi (Komfort/Sport) vs. Niveaustatusanzeige.\n</li><li><code>16</code> (<code>DtTqDistbn</code> → Powertrain): P-Port; Rad- bzw. Achsmomenten-Stellbefehle (Differenzialsperren, Kupplungsansteuerung).\n</li><li><code>17</code> (<code>DtTqDistbn</code> → HMI): P-Port; Allrad-/Verteilungsstatus.\n</li><li><code>18</code> (Body → <code>TirePMon</code>): R-Port; Umgebungstemperatur, Klemmenstatus.\n</li><li><code>19</code> (Powertrain → <code>TirePMon</code>): R-Port; Raddrehzahlen (bei indirekten RDKS-Algorithmen).\n</li><li><code>20</code> (<code>TirePMon</code> ↔ HMI): Bidirektional; Reset-/Kalibrierbefehl vs. Druckwarnungen (<em>gestrichelt: nicht im Master Table</em>).\n</li><li><code>21</code> (<code>Steer</code> → Powertrain): P-Port; Lenkleistungsbedarf (Generator-/Bordnetzvorsteuerung).\n</li><li><code>22</code> (<code>Steer</code> ↔ HMI): Bidirektional; Lenkkraft-Modusauswahl vs. Warnmeldungen.\n</li><li><code>23</code> (<code>SteerVehStabyCtrl</code> ↔ HMI): Bidirektional; Stabilitätsunterstützung Ein/Aus vs. Eingriffsanzeige.\n</li><li><code>24</code> (<code>SteerDrvrAsscSys</code> ↔ HMI): Bidirektional; Spurführungsassistenz Ein/Aus, Haptik-Feedback vs. Status.\n</li><li><code>25</code> (Mehrfachbelegung im Diagramm):\n<ul class=\"fig-list\"><li><code>Steer</code> → Body: P-Port; Lenkradwinkel für dynamisches Kurvenlicht.\n</li><li>Body → <code>PrkgAid</code>: R-Port; Ultraschallsensor- und Stoßfängerdaten, Rückwärtsgangstatus.\n</li></ul>\n</li><li><code>26</code> (Mehrfachbelegung im Diagramm):\n<ul class=\"fig-list\"><li><code>Epb</code> ↔ HMI: Bidirektional; Parkbremstaster vs. Kontrollleuchte/Zustandsrückmeldung (<em>gestrichelt: nicht im Master Table</em>).\n</li><li>Powertrain → <code>PrkgAid</code>: R-Port; Raddrehzahl-, Geschwindigkeits- und Getriebeinformationen.\n</li></ul>\n</li><li><code>27</code> (<code>PrkgAid</code> ↔ HMI): Bidirektional; Parkhilfetaster (Aktivierung/Deaktivierung) vs. akustische und optische Distanzanzeige.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Strukturmodell handelt, existieren keine expliziten UML-Lebenslinien. Die zugrundeliegenden Datenfluss- und Regelkreismuster sind:</p>\n<ul class=\"fig-list\"><li><strong>Kommunikationsparadigma:</strong> Asynchrone und zyklische <code>Sender-Receiver</code>-Kommunikation via VFB/RTE (<code>DataElements</code> ohne blockierende Client-Server-Semantik zur Gewährleistung harter Echtzeitfähigkeit).\n</li><li><strong>Arbitrierungs- und Override-Kaskade:</strong>\n<ol class=\"fig-list\"><li><em>Fahrer-/Assistenzanforderung:</em> <code>CrsCtrlAndAcc</code> generiert Beschleunigungs-/Verzögerungssollwert an <code>Vlc</code>.\n</li><li><em>Aktorkoordination:</em> <code>Vlc</code> arbitriert Anforderung gegen Antriebsgrenzen (<code>Powertrain</code>, Pfad 4) und Bremskapazität (<code>Ssm</code>/<code>Esc</code>).\n</li><li><em>Dynamischer Stabilitäts-Override:</em> Bei instabilem Fahrzustand (Übersteuern/Untersteuern) erzwingt <code>Esc</code> (Pfade 10/11) Vorrang vor <code>Vlc</code>/<code>Powertrain</code>, drosselt das Antriebsmoment und initiiert radindividuelle Bremseingriffe. Parallel generiert <code>SteerVehStabyCtrl</code> ein korrigierendes Lenkmoment über <code>Steer</code>.\n</li></ol>\n</li><li><strong>Systemzustandssteuerung:</strong> Moduswechsel im Body-Energiemanagement triggern via <code>Energy Management Status</code> Rückfallebenen (z. B. Deaktivierung von Komfort-Subfunktionen in <code>Susp</code> oder <code>CrsCtrlAndAcc</code> bei Unterspannung).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- &amp; Port-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Jede Verbindung entspricht im ARXML-Datenmodell einem <code>PortPrototype</code> (mit <code>SenderReceiverInterface</code>). \n</li><li>Die globalen Interfaces (<code>Energy Management Status</code>, <code>System Startup/Setup</code>) müssen in jedem Chassis-SW-C-Descriptor als erforderlicher R-Port instanziiert und mit den entsprechenden BSW-Mode-Managern (<code>BswM</code>) oder Body-Applikationen verbunden werden.\n</li></ul>\n</li><li><strong>Master-Table-Status (Gestrichelte Linien / Boxen):</strong>\n<ul class=\"fig-list\"><li>Schnittstellen 3, 20 und 26 sind in Release R4.0.3 noch nicht vollständig im <em>AUTOSAR Application Interfaces Master Table</em> normiert. Für diese Kommunikationspfade müssen projektspezifische Interface-Definitionen bzw. OEM-spezifische Datentypen definiert werden.\n</li></ul>\n</li><li><strong>Echtzeit- und Latenzanforderungen (Bus-Mapping):</strong>\n<ul class=\"fig-list\"><li>Regelkreise zwischen <code>Vlc</code>, <code>Esc</code>, <code>Steer</code> und <code>Powertrain</code> erfordern Zykluszeiten von ≤ 10\\,ms.\n</li><li>Werden diese SW-Cs auf verschiedene ECUs verteilt, erfordert das Bus-Mapping deterministische Frame-Übertragungen (CAN-FD, FlexRay oder Ethernet mit TSN) sowie zwingend die Konfiguration von E2E-Schutzprofilen (<code>E2E Library</code>, ASIL-D-Konformität nach ISO 26262 für Pfade 2, 4, 10, 11).\n</li></ul>\n</li><li><strong>Diagnose- und Fehlermanagement (Dem/Det):</strong>\n<ul class=\"fig-list\"><li>Ausfall von Receiver-Signalen (z. B. Timeout auf Pfad 1, 14 oder 19) muss über standardisierte FIM-Inhibition-Ketten (<code>FunctionInhibitionManager</code>) zur kontrollierten Funktionsabschaltung (Graceful Degradation) und zum Setzen relevanter DTCs im <code>Dem</code> führen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-a19913e1c85e687e", "to": "FIG-b17eda362c999ef7", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>PrkgAid</code>: Neue Software-Komponente für Parkassistenz im Fahrwerk-Domänenüberblick ergänzt.\n</li><li>Schnittstelle <code>25</code> (Body → <code>PrkgAid</code>): Neuer R-Port für Parksensordaten; erzeugt Doppelbelegung mit bestehendem P-Port <code>Steer</code> → Body.\n</li><li>Schnittstelle <code>26</code> (Powertrain → <code>PrkgAid</code>): Neuer R-Port für Fahrzustandssignale; erzeugt Doppelbelegung mit bestehender Schnittstelle <code>Epb</code> ↔ HMI.\n</li><li>Schnittstelle <code>27</code> (<code>PrkgAid</code> ↔ HMI): Neue bidirektionale Schnittstelle zur Parkassistenzbedienung und optisch-akustischen Warnung.\n</li><li><code>DtTqDibtn</code> → <code>DtTqDistbn</code>: Komponentenbezeichnung redaktionell korrigiert (Einfügen von &#x27;s&#x27;).\n</li><li><code>CrsCtrlAndAcc</code> → <code>CrsCrtlAndAcc</code>: Typografische Änderung in der Komponentenbeschriftung.\n</li><li>Legende: Typenbezeichnung von <code>Chassis domain SW-</code> zu <code>Chassis domain SW-C</code> korrigiert.\n</li></ul>"}, {"from": "FIG-b17eda362c999ef7", "to": "FIG-86fbe7eaf98ad092", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-86fbe7eaf98ad092", "to": "FIG-45135d2fddb2d9d3", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
